INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2012, 'Português', 'Interpretação de texto', 'Item 1 (TPS 2012): ADMISSÃO À CARREIRA DE DIPLOMATA PROVA OBJETIVA (1.ª FASE) Segunda Etapa LEIA COM ATENÇÃO AS INSTRUÇÕES ABAIXO. Ao receber este caderno, confira inicialmente se os seus dados pessoais, transcritos acima, estão corretos e coincidem com o que está registrado na sua folha de respostas. Confira também o seu nome em cada página numerada deste caderno. Em seguida, verifique se ele contém trinta e sete q | Caravaggio’s art is made from darkness and light. His 25 trace my first glimmering conception of the dehumanizing pictures present spotlit moments of extreme and often agonized character of slavery. I can never get rid of that conception. Those songs still follow me, to deepen my hatred of slavery, 28 and quicken my sympathies for my brethren in bonds. If any one wishes to be impressed with the soul-killing effects of slavery, let him go to Colonel Lloyd’s plantation, and, on 31 allowance-day, place himself in the deep pine woods, and there let him, in silence, analyze th', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2012, 'Economia', 'Microeconomia', 'Item 2 (TPS 2012): trabalho assalariado, de uma economia cada vez mais permeada por bens industrializados, de concentração e centralização da riqueza e dos capitais em grandes empresas, e de um mercado em franco processo de Maior potência industrial do século XIX, a Inglaterra, que optou pela mediação política de autoridades locais em suas colônias, não se beneficiou da corrida imperialista na mesma proporção alcanç | Quando autorizado pelo chefe de sala, no momento da identificação, escreva, no espaço apropriado da folha de respostas, com a sua caligrafia usual, a seguinte frase: Intenção sem ação é ilusão. Conforme previsto em edital, o descumprimento dessa instrução poderá implicar a anulação da sua prova e a sua eliminação do concurso.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2012, 'Português', 'Interpretação de texto', 'Item 3 (TPS 2012): ADMISSÃO À CARREIRA DE DIPLOMATA PROVA OBJETIVA (1.ª FASE) Segunda Etapa LEIA COM ATENÇÃO AS INSTRUÇÕES ABAIXO. Ao receber este caderno, confira inicialmente se os seus dados pessoais, transcritos acima, estão corretos e coincidem com o que está registrado na sua folha de respostas. Confira também o seu nome em cada página numerada deste caderno. Em seguida, verifique se ele contém trinta e sete q | Você encontrará dois tipos de questões objetivas: múltipla escolha e CERTO ou ERRADO. Nas questões do tipo múltipla escolha, marque, em cada uma, a única opção correta (A, B, C, D ou E), de acordo com o respectivo comando. Nas questões do tipo CERTO ou ERRADO, compostas de quatro itens cada uma, marque, para cada item, o campo designado com o código C, caso julgue o item CERTO, ou o campo designado com o código E, caso julgue o item ERRADO. OBSERVAÇÕES 4 5', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
